WITH aggregate_metric AS (SELECT mktcode,tgtcode,SUM(volume) AS total_volume,MIN(volume) AS min_volume FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 30) GROUP BY mktcode,tgtcode), candidates AS (SELECT a.mktcode,a.tgtcode,a.bizdate,m.min_volume FROM (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN aggregate_metric m ON m.mktcode=a.mktcode AND m.tgtcode=a.tgtcode WHERE m.total_volume BETWEEN 40 AND 900000000000), ranked AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(ORDER BY min_volume DESC,mktcode,tgtcode) AS rn FROM candidates) SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn<=80;
